WITH unpacked AS (SELECT id, created_at, coupon_codes, items, ship_to, ARRAY_MAX(TRANSFORM(items, li -> li.price)) AS max_item_price, COALESCE(attributes['device'], 'none') AS device_or_default, ARRAY_JOIN(ARRAY_SORT(coupon_codes), ',') AS coupons_text, ship_to.city AS ship_city, ARRAY_CONTAINS(MAP_KEYS(attributes), 'device') AS has_device FROM carts) SELECT ship_city, DATE_TRUNC('DAY', created_at) AS activity_day, COUNT(DISTINCT ship_city) AS distinct_ship_cities, ROUND(SUM(max_item_price) / NULLIF(COUNT(CASE WHEN ship_city = 'London' THEN 1 END), 0), 2) AS max_item_price_per_london, MAX(created_at) AS last_seen FROM unpacked GROUP BY ship_city, DATE_TRUNC('DAY', created_at) ORDER BY activity_day DESC NULLS FIRST
